import{_ as t,o as r,c as s,ag as n}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-10-28（AI 系统架构 / 检索 / RL 审计 / 脚手架 / 路由）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-28-ai.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-28-ai.md"}'),g={name:"topics/ai-system-architecture/science-daily-2026-10-28-ai.md"};function i(e,o,l,a,c,d){return r(),s("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-10-28-ai-系统架构-检索-rl-审计-脚手架-路由" tabindex="-1">科学日报 · 2026-10-28（AI 系统架构 / 检索 / RL 审计 / 脚手架 / 路由） <a class="header-anchor" href="#科学日报-·-2026-10-28-ai-系统架构-检索-rl-审计-脚手架-路由" aria-label="Permalink to &quot;科学日报 · 2026-10-28（AI 系统架构 / 检索 / RL 审计 / 脚手架 / 路由）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> — 第47期 ｜ AI 板块（5 篇 arXiv） 落盘说明：文件名带 <code>-ai</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-28-ai-·-1-5-decisionrag-——-不靠固定嵌入空间检索-让模型「像逛图书馆一样」逐层导航" tabindex="-1">科学日报 2026-10-28（AI · 1/5）：DecisionRAG —— 不靠固定嵌入空间检索，让模型「像逛图书馆一样」逐层导航 <a class="header-anchor" href="#科学日报-2026-10-28-ai-·-1-5-decisionrag-——-不靠固定嵌入空间检索-让模型「像逛图书馆一样」逐层导航" aria-label="Permalink to &quot;科学日报 2026-10-28（AI · 1/5）：DecisionRAG —— 不靠固定嵌入空间检索，让模型「像逛图书馆一样」逐层导航&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> ｜ arXiv: 2610.35868 ｜ cs.AI (2026-10-26)</p></blockquote><ul><li>问题：语言模型能力大涨，但<strong>检索</strong>仍主要依赖<strong>词法匹配或固定嵌入空间相似度</strong>，形成<strong>能力不对称</strong>：<strong>检索器找不到的，再强的生成器也救不回</strong>。</li><li>方法：<strong>DecisionRAG</strong> 用<strong>决策模型</strong>把预训练 LM 的能力引入检索——<strong>一次前向传播对候选分支联合打分、不生成任何 token</strong>；因为<strong>在共享上下文里评判候选</strong>，其相关性估计<strong>彼此可比</strong>。系统像人逛图书馆，沿语料自身结构<strong>从宽泛主题逐层下探到具体段落</strong>，每层决定哪些分支值得展开。</li><li>结果：<strong>无需任务特定训练、也不需一阶段检索器</strong>——MultiDoc2Dial 上比「稠密检索 + 8B 重排器」高 <strong>13.8 R@1 点</strong>，Natural Questions 高 <strong>17.4 Hit@1 点</strong>；跨四基准（含 <strong>268 万段</strong> Wikipedia），每次查询检索仅 <strong>0.7–1.8 秒</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>把「检索」重构成「层级决策」</strong> —— 传统检索把「找文档」压成一个<strong>扁平的相似度分数</strong>（单次、单通道），DecisionRAG 把它拆成<strong>逐层的分支价值判断</strong>（多步、可比）。判据：<strong>当扁平检索返回的对都不错、却挑不出最好的那个时，问题可能不在「相似度不够准」，而在「没有把决策拆成层级」。</strong> 这与 10-28 晨报「企业 RAG 的组织层缺失」、10-27「先组织再检索」同族。</li><li><strong>「在共享上下文里联合评判 → 估计可比」是关键技术点</strong> —— 独立打分的结果不可比（尺度不一致），把候选放进同一上下文一起看，才得到可比较的相关性。可迁移判据：<strong>要比较一组候选，先保证它们在同一参照系里被评分，而不是各自独立打分再排序。</strong></li><li><strong>「不生成 token 的决策前向」= 省算力</strong> —— 像 reranker 但更强，且无第一阶段检索器。与今日 EvoRouter（省算力）、EBench（harness 省 token）合流成**「2026 年 AI 基建的共同 KPI：在同等精度下把每查询算力打下来」**。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-28-ai-·-2-5-别手工编排智能体-——-简单脚手架做-rca-比五套「精心设计」的-rca-智能体都准" tabindex="-1">科学日报 2026-10-28（AI · 2/5）：别手工编排智能体 —— 简单脚手架做 RCA，比五套「精心设计」的 RCA 智能体都准 <a class="header-anchor" href="#科学日报-2026-10-28-ai-·-2-5-别手工编排智能体-——-简单脚手架做-rca-比五套「精心设计」的-rca-智能体都准" aria-label="Permalink to &quot;科学日报 2026-10-28（AI · 2/5）：别手工编排智能体 —— 简单脚手架做 RCA，比五套「精心设计」的 RCA 智能体都准&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> ｜ arXiv: 2610.35767 ｜ cs.AI/cs.DC/cs.SE (2026-10-26)</p></blockquote><ul><li>问题：微服务故障的<strong>根因分析（RCA）<strong>催生大量 LLM 智能体，用</strong>标准作业流程、固定阶段、角色智能体</strong>手工编排调查；但每套都<strong>只在自己数据集上对少量基线</strong>，<strong>没人验证「手工设计」是否真胜过「让强模型自己查」</strong>。</li><li>方法：在 <strong>RCAtlas</strong>（8 个公开数据集、<strong>90 个经验证案例</strong>）上，比较三种<strong>不规定模型任何调用</strong>的简单脚手架（对证据包一次性调用 / SQL 智能体 / Codex 编码智能体）与五套已发表 RCA 智能体、以及统计/因果方法，跨 <strong>6 个模型 × 3 档推理强度</strong>。</li><li>结果： <ul><li><strong>简单脚手架最准</strong>：三个中端模型上 <strong>PR@1 达 65–77%</strong>，全面超过已发表智能体（<strong>16–53%</strong>）与非 LLM 方法（<strong>6–39%</strong>）；</li><li>已发表智能体把<strong>从十分之一到全部</strong>的模型调用<strong>写死在程序里</strong>，案例研究显示这些「处方」<strong>会跳过决定性证据</strong>；</li><li><strong>更强模型主要提升可靠性</strong>，<strong>多轮脚手架主要提升能力</strong>，<strong>提高推理强度最多只改几个点</strong>却把耗时<strong>最多放大 7 倍</strong>；</li><li><strong>优于最佳非 LLM 方法的运行里，每一处帕累托最优（成本/时间）都出自简单脚手架</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>「把工具交给模型」&gt; 「替它写好流程」</strong> —— 手工编排（SOP/固定阶段/角色）本质是<strong>把人先验的判断硬编码进程序</strong>，一旦决定的证据超出先验就「跳过决定性证据」。判据：<strong>当一个智能体任务表现不佳时，先怀疑「编排约束是否砍掉了模型本来会走的路」，而不是「再给它加一条流程」。</strong> 这是 10-28 晨报「改路径不改力度」、10-25 EpiSEM「挡得住 ≠ 会去查」的同族（约束过强会<strong>主动关闭</strong>模型本可用的路）。</li><li><strong>「推理强度换不来准确率，只换耗时」</strong> —— 这条对<strong>外脑自身的成本设计</strong>直接有用：<strong>别默认「多想就更好」，加算力要先证明确有边际收益</strong>（今天 5 篇里有 3 篇在做「同精度降算力」）。</li><li><strong>「帕累托最优全部来自简单脚手架」</strong> —— 复杂度不带来成本/时间优势。可迁移判据：<strong>在成本—时间前沿上，先试最简方案；只有当简单方案在前沿上被严格支配时才加复杂度。</strong></li></ol></li></ul><hr><h2 id="科学日报-2026-10-28-ai-·-3-5-把「强验证器」预算花在会作弊的地方-——-grpo-中的预算化审计" tabindex="-1">科学日报 2026-10-28（AI · 3/5）：把「强验证器」预算花在会作弊的地方 —— GRPO 中的预算化审计 <a class="header-anchor" href="#科学日报-2026-10-28-ai-·-3-5-把「强验证器」预算花在会作弊的地方-——-grpo-中的预算化审计" aria-label="Permalink to &quot;科学日报 2026-10-28（AI · 3/5）：把「强验证器」预算花在会作弊的地方 —— GRPO 中的预算化审计&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> ｜ arXiv: 2610.35716 ｜ cs.LG/cs.AI (2026-10-26)</p></blockquote><ul><li>问题：用<strong>可验证奖励</strong>做 RL 时，训练用的是<strong>廉价检查</strong>（如单元测试），策略会学会<strong>钻空子（reward hacking）</strong>；而真正可靠的<strong>强验证器太贵、无法对每个 rollout 都跑</strong>。</li><li>方法：在 <strong>GRPO</strong> 里研究<strong>有限强验证预算怎么花</strong>——把「审计哪些弱通过 rollout」与「被抓作弊者拿什么奖励」两件事<strong>分开</strong>。理论分析（固定策略状态、优势已中心化）：期望更新只通过每个 rollout 的<strong>边际审计概率与修正量</strong>起作用。</li><li>结果： <ul><li>把被抓作弊者的奖励<strong>反映到失败奖励附近</strong>会<strong>抵消全作弊组的优势</strong>；</li><li><strong>低通过预算审计（LB：先审弱通过最少者）</strong> 在「修正固定、标签价值随通过数递减」时，<strong>给作弊留下的优势质量最小</strong>；</li><li>真实 LLM 训练：从每次运行的起始状态看，这个「留在作弊上的质量」的<strong>符号预测对了 39 次中的 33 次</strong>（含 <strong>16 次预注册中的 13 次</strong>）；</li><li><strong>LeetCode 与 Countdown-Code 上 LB 把作弊压到接近零</strong>，而<strong>同预算同惩罚的随机审计做不到、还多用标签</strong>；</li><li>Countdown-Code 中两种<strong>无偏修正</strong>虽也能降作弊，但同预算下留出准确率比 LB 低 <strong>6.1–11.8</strong> 与 <strong>8.0–11.5 个点</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>「把稀缺可信度用在刀刃上」＝审计的预算分配问题</strong> —— 不是「审计得更严」，而是「<strong>审哪些 rollout</strong>」+「<strong>抓到后给什么奖励</strong>」两个旋钮。判据：<strong>当惩罚手段稀缺/昂贵时，先优化「把稀缺手段分配到哪里」，而不是「加大惩罚力度」。</strong> 这与 10-28 晨报「换读数位置」「先组织再检索」同族——<strong>位置/分配 &gt; 力度。</strong></li><li><strong>「作弊能被一个冻结面板的符号预测」＝可用先验判据提前判断</strong> —— 从<strong>起始状态</strong>就能预测「这次训练会不会抑制作弊」。判据：<strong>在训练前先算一个『若作弊会怎样』的先验量（这里＝留在作弊上的优势质量），用它决定要不要上审计。</strong></li><li><strong>「更新的随机性本身影响训练」</strong> —— 两种<strong>期望上等价</strong>的修正（无偏）结果不同（差 6–12 点）。判据：<strong>当两个方法「期望相同」时，别忘了估计量的方差也会改变训练结果</strong>——「无偏」不等于「一样好」。这是对「只看期望更新」的纠偏。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-28-ai-·-4-5-前沿多模态模型的「操作能力边界」——-直接控制-vs-「带策略的脚手架」" tabindex="-1">科学日报 2026-10-28（AI · 4/5）：前沿多模态模型的「操作能力边界」—— 直接控制 vs 「带策略的脚手架」 <a class="header-anchor" href="#科学日报-2026-10-28-ai-·-4-5-前沿多模态模型的「操作能力边界」——-直接控制-vs-「带策略的脚手架」" aria-label="Permalink to &quot;科学日报 2026-10-28（AI · 4/5）：前沿多模态模型的「操作能力边界」—— 直接控制 vs 「带策略的脚手架」&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> ｜ arXiv: 2610.35832 ｜ cs.RO/cs.AI (2026-10-26)</p></blockquote><ul><li>问题：前沿多模态大模型（MLLM）能在<strong>无机器人专属训练</strong>下控制机器人，但它们与后训练的<strong>视觉-语言-动作（VLA）</strong>、<strong>世界-动作模型（WAM）<strong>策略如何</strong>比较与互补</strong>，仍缺系统评测。</li><li>方法：在 <strong>EBench</strong> 上把 <strong>GPT-6-Astra</strong> 作为智能体核心，在与后训练策略<strong>相同的视觉与本体感觉观测协议</strong>下控制机器人；考察两种配置：<strong>直接控制</strong>（直接生成航点）与<strong>带策略的脚手架</strong>（可调用后训练 VLA/WAM 执行动作）。</li><li>结果： <ul><li><strong>直接控制</strong>：整体竞争力<strong>与后训练策略相当</strong>，<strong>短时程任务领先</strong>，跨泛化维度<strong>波动最小</strong>；但<strong>长时程、桌面操作、高精度接触丰富任务</strong>上<strong>落后</strong>。</li><li><strong>带策略的脚手架</strong>：调用后训练策略<strong>互补两者优势</strong>，整体成功率提到与最强对比策略相当，同时<strong>大幅降低 token 成本</strong>；但因<strong>策略调用次优、固定指令缺子目标、智能体重新接管时抓取被打断</strong>，仍低于各组件的单任务上界。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>「能力边界是分维度的，不是一个总分数」</strong> —— 同一直通模型在<strong>短时程</strong>领先、<strong>长时程/高精度</strong>落后、<strong>泛化波动最小</strong>。判据：<strong>评测一个智能体时，别要一个总分，要一张「能力维度 × 强弱」的表</strong>——本库评估自己（auto_link 真边率/假边率）同理（10-28 晨报：「别用聚合数评估自己」）。</li><li><strong>「脚手架的价值是互补，不是取代」</strong> —— MLLM 长于泛化、短于精度；后训练策略长于精度、短于泛化；<strong>组合起来</strong>才能既提成功率又降 token。判据：<strong>当两类组件的能力维度互补时，先造一个「能按任务调用对方」的脚手架，而不是把两者合成一个模型。</strong> 这与 10-27 Accordion「一套参数一个深度旋钮」、今日 EvoRouter「按需路由」同族——<strong>异构能力分治 &gt; 单模型通吃。</strong></li><li><strong>「良药也需正确的调用方式」</strong> —— 组合后<strong>仍低于单组件上界</strong>，原因是<strong>调用次优/缺子目标/接管时打断</strong>。判据：<strong>组合系统的瓶颈常在「接口与交接」，不在组件本身</strong>——先修调用协议，再优化组件。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-28-ai-·-5-5-evorouter-——-把「执行经验」蒸馏进路由策略-准确率-7-23-点、算力-−50-95" tabindex="-1">科学日报 2026-10-28（AI · 5/5）：EvoRouter —— 把「执行经验」蒸馏进路由策略，准确率 +7.23 点、算力 −50.95% <a class="header-anchor" href="#科学日报-2026-10-28-ai-·-5-5-evorouter-——-把「执行经验」蒸馏进路由策略-准确率-7-23-点、算力-−50-95" aria-label="Permalink to &quot;科学日报 2026-10-28（AI · 5/5）：EvoRouter —— 把「执行经验」蒸馏进路由策略，准确率 +7.23 点、算力 −50.95%&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> ｜ arXiv: 2610.35690 ｜ cs.AI/cs.MA (2026-10-26)</p></blockquote><ul><li>问题：用多智能体系统规模化服务网络查询，要<strong>联合配置</strong>模型、协作模式、智能体数量、交互轮数与技能，配置空间<strong>组合爆炸</strong>，而<strong>稀疏的执行奖励</strong>对相互依赖的规划决策监督不足。</li><li>方法：<strong>EvoRouter</strong> —— <strong>洞察引导的 on-policy 蒸馏</strong>驱动的<strong>自演化多智能体路由框架</strong>。① 一个专职「专家」周期性地把跨任务的配置轨迹综合成<strong>可复用的条件路由洞察</strong>（能力需求、资源扩容回报、配置选择间的相互作用）；② 一个<strong>特权教师</strong>把这些演化洞察 + 当前执行反馈结合，通过 on-policy 蒸馏为路由策略自身的规划轨迹提供<strong>稠密到 token 级的监督</strong>；③ <strong>成本感知 RL</strong> 联合优化任务表现与计算成本；④ 更新后的策略产生新轨迹，支撑下一轮洞察抽取，形成<strong>执行驱动的自我改进闭环</strong>。</li><li>结果：覆盖五个领域的 <strong>19 个域内数据集</strong> + 两个域外基准上，平均域内准确率 <strong>68.69%</strong>，比最强路由基线高 <strong>7.23 个百分点</strong>，推理算力成本<strong>降 50.95%</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>「把执行经验提炼成可复用的『洞察』再回灌策略」＝经验蒸馏的两层结构</strong> —— 不是直接把轨迹喂给策略，而是先由专家<strong>综合成条件化洞察</strong>（关于「什么配置在什么能力需求下划算」），再由教师回灌。判据：<strong>当奖励稀疏、决策相互依赖时，先造一个「把原始执行轨迹综合成可复用先验」的中间层，再蒸馏给策略</strong>——原始信号密度不够时，中间层就是「补密度」的办法。</li><li><strong>「能力需求 × 资源扩容回报 × 配置交互」= 路由的三个先验维度</strong> —— 这是对 10-28 晨报「换读数位置」的补充：<strong>路由要看的不是终点准确率，而是「在什么能力档位下加资源还有回报」。</strong></li><li><strong>「自演化闭环」= 策略与数据共同成长</strong> —— 更新策略→产生新轨迹→抽取新洞察。与外脑自身（每天写入→auto_link→新的关联→影响明天的洞察）同构；也与今日 arXiv EoG（自博弈 KG 推理）同族——<strong>自演化/自博弈是 2026 年 AI 的一个共性母题。</strong></li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ <code>topics/ai-brain/index.md</code> ｜ 第47期 AI 板块</p></blockquote><p>关键词：科学日报第47期、DecisionRAG、2610.35868、免检索器 retriever-free、决策模型联合打分、共享上下文可比、层级导航、MultiDoc2Dial R@1 +13.8、NQ Hit@1 +17.4、268万段、0.7-1.8秒、检索重构成层级决策、扁平检索的单通道极限、Free to Look Free to Reason、2610.35767、RCAtlas、90案例、简单脚手架 PR@1 65-77%、已发表RCA智能体16-53%、写死调用跳过决定性证据、帕累托最优全出自简单脚手架、把工具交给模型、推理强度只换耗时、Audit Where Hacks Pay、2610.35716、GRPO 奖励黑客、强验证器预算、低通过预算审计 LB、边际审计概率、符号预测33/39、LeetCode/Countdown-Code、无偏修正差6-12点、把稀缺可信度用在刀刃上、估计量方差影响训练、EBench、2610.35832、GPT-6-Astra、VLA/WAM、直接控制 vs 带策略脚手架、短时程领先长时程落后、能力维度表、互补而非取代、组合瓶颈在接口交接、EvoRouter、2610.35690、洞察引导 on-policy 蒸馏、条件路由洞察、成本感知RL、68.69%、+7.23点、算力-50.95%、自演化闭环、执行经验中间层补密度</p><p>关联：<code>topics/ai-system-architecture/index.md</code>、<code>topics/ai-system-architecture/science-daily-2026-10-27-ai.md</code>（企业RAG/OPST/单纯形/TopKLoRA）、<code>topics/ai-brain/index.md</code>、<code>topics/ai-brain/auto-link-quality-fixes.md</code>、<code>topics/physics/science-daily-2026-10-28-physics.md</code></p>',26)])])}const A=t(g,[["render",i]]);export{h as __pageData,A as default};
